function evaluate(report,task){
 const r=report||{},ps=r.parties||[],vs=r.vehicles||[],ev=(r.evidence||'').toLowerCase();
 const checks=[['Titel vorhanden',!!r.title?.trim()],['Vorgangsart korrekt',r.type===task.type],['Datum korrekt',r.date===task.date],['Tatzeit korrekt',r.time===task.time],['Ort korrekt',(r.place||'').trim().toLowerCase()===task.place.toLowerCase()],['PLZ korrekt',r.postal===task.postal],['Personen und Rollen vollständig',ps.length===task.parties.length&&task.parties.every(([id,role])=>ps.some(p=>p.id===id&&p.role===role))],['Fahrzeuge korrekt zugeordnet',JSON.stringify([...vs].sort())===JSON.stringify([task.vehicle,task.extraVehicle].filter(Boolean).sort())],['Beweismittelkennungen erfasst',task.evidence.every(e=>ev.includes(e.split(' · ')[0].toLowerCase()))],['Sachverhalt ausgefüllt',!!r.facts?.trim()],['Aussagen dokumentiert',!!r.statements?.trim()],['Maßnahmen und offener Stand dokumentiert',!!r.actions?.trim()]];
 return {checks,correct:checks.filter(c=>c[1]).length,total:checks.length};
}
