function load(){if(owner===uid()&&state)return;owner=uid();state=null;try{state=JSON.parse(localStorage.getItem(key()))}catch{}if(!state||state.version!==2)state={version:2,people:[],vehicles:[],weapons:[],warrants:[],bolos:[],items:[],reports:[],results:[],run:null};tab='Übersicht';editing=null;choosing=false;search='';}
