function area(label,name,value='',required=false,placeholder=''){return `<label>${E(label)} ${required?'<i>*</i>':''}<textarea name="${name}" rows="5" maxlength="12000" ${required?'required':''} placeholder="${E(placeholder)}">${E(value)}</textarea></label>`}
const empty=()=>({id:id(),number:state.reports.reduce((n,r)=>Math.max(n,r.number||0),0)+1,title:'',template:'incident',type:'',date:'',time:'',place:'',postal:'',status:'Entwurf',tags:'',parties:[],vehicles:[],officers:[],officerStatements:[],charges:[],facts:'',statements:'',actions:'',evidence:'',extra:{},author:current.name||current.username||'Officer',created:now()});
