function home(){const nw=state.warrants.filter(w=>w.status==='Aktiv'),nb=state.bolos.filter(w=>w.status==='Aktiv'),max=Math.max(1,state.reports.length,nw.length,nb.length);return headline('Übersicht',`Willkommen zurück, ${E(current.name||current.username)}.`,`<button class="cad-primary" data-cad="new">＋ Neuer Report</button>`)+`<p class="cad-date">▣ ${new Date().toLocaleString('de-DE',{dateStyle:'full',timeStyle:'short'})}</p><div class="cad-stats"><section class="cad-panel"><div class="cad-flex cad-between"><b>▥ Aktivität</b><small>Gesamt</small></div><h2>${state.reports.length} <small>Reports</small></h2><div class="cad-bars">${[['Reports',state.reports.length],['Warrants',nw.length],['Fahndung',nb.filter(x=>x.category==='Person').length],['BOLOs',nb.length]].map(([l,n],i)=>`<div><small>${n}</small><i style="height:${Math.max(2,65*n/max)}px;background:${['#1ac9e0','#ef4444','#f5a623','#518bff'][i]}"></i><small>${l}</small></div>`).join('')}</div></section><section class="cad-panel"><div class="cad-flex cad-between"><b>▥ Verteilung</b><small>Aktuell</small></div>${[['Reports',state.reports.length],['Warrants',nw.length],['Fahndung',nb.filter(x=>x.category==='Person').length],['BOLOs',nb.length]].map(([l,n])=>`<div class="cad-meter"><span>${l}</span><i><b style="width:${n/max*100}%"></b></i><small>${n}</small></div>`).join('')}</section><section class="cad-panel"><b>♟ Diensthabend</b><div class="cad-flex cad-officer"><span class="cad-symbol">♟</span><div><small>Officer</small><h3>${E(current.name||current.username)}</h3><small>${E(current.serviceNo||'—')} · Mission Row Police Department</small></div></div><hr><div class="cad-flex"><div><small>Offene Warrants</small><h3>${nw.length}</h3></div><div><small>Zur Fahndung</small><h3>${nb.filter(x=>x.category==='Person').length}</h3></div></div></section></div><h4>♟ Zur Fahndung ausgeschrieben</h4><div class="cad-empty-block">${nb.length?nb.map(x=>`<div class="cad-wanted"><span>♟</span>${badge('GESUCHT','red')}<b>${E(x.title)}</b></div>`).join(''):'Keine aktiven Fahndungen.'}</div><div class="cad-home-lists"><section class="cad-panel"><div class="cad-flex cad-between"><b>▤ Letzte Reports</b><button data-go="Reports">Alle ansehen</button></div>${state.reports.length?state.reports.slice(-5).reverse().map(r=>`<button class="cad-report-link" data-open-report="${r.id}"><b>▤ ${E(r.title||'Unbenannter Entwurf')}</b><span>${E(r.author)} · ${E(r.created)}</span></button>`).join(''):'<p class="cad-muted">Noch keine Reports angelegt.</p>'}</section><section class="cad-panel"><div class="cad-flex cad-between"><b>⚒ Offene Warrants</b><button data-go="Warrants">Alle ansehen</button></div>${nw.map(w=>`<button class="cad-report-link" data-edit="warrants:${w.id}">${E(pname(w.person))}<small>${E(w.reason)}</small></button>`).join('')||'<p class="cad-muted">Keine offenen Warrants.</p>'}</section></div>`}
